-- Article français « Hanouka 2026 en Israël », fourni et relu par Shana (25/11/2026), publié
-- directement (pas de validation supplémentaire). Format « une langue par article ».
begin;
insert into public.journal_posts
  (slug, lang, category, author_name, title, seo_title, meta_description, intro, body, booking_intro, conclusion, faq,
   cover_image, cover_alt, primary_keyword, linked_listings, internal_links, topic_id, pipeline_status, published_at)
select 'hanouka-2026-israel', 'fr', 'Guides', 'STAYMAKOM',
  'Hanouka 2026 en Israël : que faire pendant les 8 jours de fête',
  'Hanouka 2026 en Israël : que faire pendant la fête',
  'Hanouka 2026 se fête du 4 au 12 décembre. Nos idées pour vivre la fête en Israël : Jérusalem, sorties en famille, gourmandises et Shabbat.',
  'Hanouka 2026 commence le vendredi 4 décembre au coucher du soleil et se termine le samedi 12 décembre. Pendant huit soirs, les hanoukiot s''allument aux fenêtres, les boulangeries débordent de soufganiot et Jérusalem devient le cœur de la fête. Voici nos idées pour la vivre pleinement en Israël.', '[{"heading": "Hanouka 2026 : les dates", "paragraphs": ["La première bougie s''allume le vendredi 4 décembre au soir, la huitième le vendredi 11 décembre, et la fête se termine à la tombée de la nuit le samedi 12. Particularité de cette année : Hanouka commence et se termine un Shabbat. Les deux vendredis soir, on allume les bougies de Hanouka juste avant celles de Shabbat.", "En Israël, Hanouka n''est pas un jour férié : les commerces, les restaurants et la plupart des sites restent ouverts. Les écoles ferment en revanche une partie de la semaine. Les familles sortent beaucoup, et les activités les plus demandées se remplissent vite."]}, {"heading": "Jérusalem, là où tout a commencé", "paragraphs": ["Hanouka célèbre la reconquête du Temple de Jérusalem par les Maccabées et sa nouvelle inauguration, il y a plus de 2 000 ans. Passer la fête dans la ville où l''histoire s''est déroulée lui donne une autre dimension.", "Commencez sous terre : une visite guidée de la Cité de David vous fait traverser d''anciens canaux et se termine par la traversée du [**tunnel d''Ézéchias**](/standalone-experience/biblical-city-of-david-guided-tour-hezekiah-tunnel), les pieds dans une eau de source qui coule depuis près de 3 000 ans (3 heures, à partir de ₪95). Remontez ensuite la [**Voie des Pèlerins**](/standalone-experience/pilgrimage-road-guided-tour-jerusalem), la rue récemment dégagée que gravissaient les pèlerins pour rejoindre le Temple à l''époque du Second Temple, ce même Temple dont Hanouka célèbre la nouvelle inauguration (2 heures, à partir de ₪95).", "Le soir, le [**spectacle son et lumière Hallelujah**](/standalone-experience/hallelujah-night-show-jerusalem) transforme les murailles antiques de la Cité de David en scène et raconte l''histoire de Jérusalem en une heure environ (à partir de ₪99)."]}, {"heading": "Hanouka en famille", "paragraphs": ["Écoles fermées, Hanouka est la grande semaine des familles en Israël. À Jérusalem, trois sorties plaisent à tous les âges :"], "bullets": ["[**Le tamisage archéologique**](/standalone-experience/archaeological-sifting-emek-tzurim-jerusalem) : les enfants tamisent de la vraie terre issue des fouilles de la Cité de David et cherchent pièces, poteries et perles (90 minutes, à partir de ₪50, ₪45 pour les enfants).", "[**Un voyage animé dans l''histoire de Jérusalem**](/standalone-experience/time-elevator-jerusalem) : 35 minutes sur des sièges en mouvement pour traverser 3 000 ans d''histoire, à deux pas de la porte de Jaffa (à partir de ₪79).", "**L''allumage des bougies au Kotel** : chaque soir de Hanouka, une immense hanoukia est allumée sur l''esplanade du mur Occidental. C''est gratuit, et les enfants s''en souviennent."]}, {"heading": "Soufganiot, latkes et gourmandises", "paragraphs": ["En Israël, Hanouka a le goût de l''huile et du sucre. Dès début décembre, toutes les boulangeries alignent les soufganiot, ces beignets fourrés à la confiture, à la crème de pistache ou au chocolat. Les latkes, galettes de pommes de terre, se dégustent plutôt en famille qu''au restaurant.", "**Où trouver les meilleures soufganiot**", "Oubliez les grandes chaînes : les soufganiot les plus intéressantes viennent de petites boulangeries et de chefs pâtissiers qui réinventent leur collection chaque année. Les adresses qui se sont distinguées l''an dernier, à retester en 2026 :"], "bullets": ["**Dallal, Neve Tzedek (Tel Aviv)** : la soufganiya façon cinnamon roll de la cheffe pâtissière Timor Lavi est arrivée en tête du classement Time Out Tel Aviv 2025.", "**Amita, Tel Aviv** : une jeune pâtisserie à deux adresses (rues Salameh et Bialik), avec une soufganiya ganache chocolat noir pour les puristes.", "**Senyora, Florentin (Tel Aviv)** : la boulangerie de quartier qui a transformé le carrot cake en beignet.", "**The Little Bakers, Tel Aviv** : figues et balsamique, pour un Hanouka sucré-salé.", "**Teller, Jérusalem** : la boulangerie artisanale à côté du marché Mahane Yehuda, régulièrement citée comme la meilleure de la ville par la presse locale.", "**Kadosh, Jérusalem** : un café-pâtisserie rue Shlomtzion HaMalka, en centre-ville, réputé pour ses créations raffinées à la française."], "paragraphs_after": ["Comptez environ ₪14 à ₪22 pour une soufganiya de chef. Si la cacheroute compte pour vous, vérifiez le certificat affiché en boutique.", "Pour prolonger le côté gourmand de la fête, deux idées hors de Jérusalem : une [**dégustation de chocolat dans le noir complet, au port de Jaffa**](/standalone-experience/chocolate-tasting-workshop-in-the-dark-jaffa), où l''on goûte avec tous les sens sauf la vue (90 minutes, à partir de ₪185), ou une [**dégustation vin et chocolat en famille près de Zichron Yaakov**](/standalone-experience/chocolate-hour-in-the-vines), où les enfants ont leur propre coffret de chocolats (environ 1 heure, à partir de ₪125, ₪80 pour les enfants)."]}, {"heading": "Un Shabbat de Hanouka à Jérusalem", "paragraphs": ["Hanouka 2026 compte deux Shabbat (du 4 au 5 et du 11 au 12 décembre) : c''est le moment idéal pour passer un vendredi soir à Jérusalem. Notre séjour Shabbat à [**The Inbal Jerusalem**](/experience/shabbat-inbal-jerusalem) commence par un Kabbalat Shabbat à quelques minutes de l''hôtel, puis un Shabbat festif à deux pas des remparts de la vieille ville (à partir de ₪1 991)."]}, {"heading": "Nos conseils pratiques", "paragraphs": [], "bullets": ["**Météo** : les soirées de décembre sont froides à Jérusalem. Prévoyez des couches chaudes, et des chaussures d''eau pour le tunnel d''Ézéchias.", "**Réservez tôt** : les activités en famille et les séjours du vendredi soir partent en premier pendant la semaine de Hanouka.", "**Les vendredis** : les bougies s''allument avant l''entrée de Shabbat. Organisez-vous pour être rentrés avant le coucher du soleil."]}]'::jsonb, null, 'Hanouka est l''une des plus belles semaines pour découvrir Israël : des lumières à chaque fenêtre, des gourmandises à chaque coin de rue et Jérusalem au sommet de son émotion. Réservez vos expériences avant la cohue, ou écrivez à notre équipe sur WhatsApp : on vous aide à organiser vos huit soirs.', '[{"question": "Quand commence Hanouka 2026 ?", "answer": "Le vendredi 4 décembre 2026 au coucher du soleil. La huitième bougie s''allume le vendredi 11 décembre, et la fête se termine le samedi 12 décembre à la tombée de la nuit."}, {"question": "Tout est-il ouvert en Israël pendant Hanouka ?", "answer": "Oui. Hanouka n''est pas un jour férié en Israël : commerces, restaurants et sites restent ouverts. Les écoles ferment une partie de la semaine, il y a donc plus de familles dans les lieux de sortie."}, {"question": "Où passer Hanouka en Israël ?", "answer": "À Jérusalem, là où se déroule l''histoire de Hanouka. La Cité de David, la Voie des Pèlerins et la vieille ville font revivre l''époque des Maccabées."}, {"question": "Que faire à Jérusalem avec des enfants pendant Hanouka ?", "answer": "Le tamisage archéologique, le voyage animé dans l''histoire de la ville et le spectacle Hallelujah à la Cité de David plaisent aux petits comme aux grands."}, {"question": "Que mange-t-on à Hanouka en Israël ?", "answer": "Des soufganiot (beignets fourrés) et des latkes (galettes de pommes de terre), frits dans l''huile en souvenir du miracle de la fiole d''huile qui a brûlé huit jours."}]'::jsonb,
  (select hero_image from public.standalone_experiences where slug = 'biblical-city-of-david-guided-tour-hezekiah-tunnel'),
  'Visite guidée de la Cité de David et du tunnel d''Ézéchias à Jérusalem',
  'hanouka en israël', jsonb_build_array((select jsonb_build_object('id', id, 'kind', 'standalone', 'path', '/standalone-experience/' || slug) from public.standalone_experiences where slug = 'biblical-city-of-david-guided-tour-hezekiah-tunnel' and status = 'published'), (select jsonb_build_object('id', id, 'kind', 'standalone', 'path', '/standalone-experience/' || slug) from public.standalone_experiences where slug = 'time-elevator-jerusalem' and status = 'published'), (select jsonb_build_object('id', id, 'kind', 'standalone', 'path', '/standalone-experience/' || slug) from public.standalone_experiences where slug = 'chocolate-tasting-workshop-in-the-dark-jaffa' and status = 'published'), (select jsonb_build_object('id', id, 'kind', 'experience', 'path', '/experience/' || slug) from public.experiences2 where slug = 'shabbat-inbal-jerusalem' and status = 'published')), array['/standalone-experience/biblical-city-of-david-guided-tour-hezekiah-tunnel', '/standalone-experience/pilgrimage-road-guided-tour-jerusalem', '/standalone-experience/hallelujah-night-show-jerusalem', '/standalone-experience/archaeological-sifting-emek-tzurim-jerusalem', '/standalone-experience/time-elevator-jerusalem', '/standalone-experience/chocolate-tasting-workshop-in-the-dark-jaffa', '/standalone-experience/chocolate-hour-in-the-vines', '/experience/shabbat-inbal-jerusalem'],
  (select id from public.blog_topics where lang = 'fr' and primary_keyword = 'hanouka en israël'),
  'published', now()
where not exists (select 1 from public.journal_posts where slug = 'hanouka-2026-israel');
